const {GuestConversion}=await import(pathToFileURL(join(temporary,'GuestConversion.mjs')).href);
test('guest conversion shows email confirmation before password entry and preserves permanent account identity',async()=>{
 const client=new QueryClient({defaultOptions:{queries:{retry:false,staleTime:Infinity}}}),render=()=>renderToStaticMarkup(createElement(QueryClientProvider,{client},createElement(GuestConversion,{userId:'conversion-user'})));
 client.setQueryData(['guest-conversion','conversion-user'],{guest:true,email:null,pending:false,email_ready:false,account_id:'conversion-user'});const email=render();assert.match(email,/Transformer mon compte invité/);assert.match(email,/type="email"/);assert.doesNotMatch(email,/type="password"/);assert.match(email,/carte d’accès restent en place/);
 client.setQueryData(['guest-conversion','conversion-user'],{guest:true,email:'member@example.invalid',pending:true,email_ready:false,account_id:'conversion-user'});assert.match(render(),/Renvoyer le lien/);
 client.setQueryData(['guest-conversion','conversion-user'],{guest:true,email:'member@example.invalid',pending:false,email_ready:true,account_id:'conversion-user'});const ready=render();assert.equal((ready.match(/type="password"/g)??[]).length,2);assert.match(ready,/Activer mon compte permanent/);
 client.setQueryData(['guest-conversion','conversion-user'],{guest:false,email:'member@example.invalid',pending:false,email_ready:true,account_id:'conversion-user'});assert.match(render(),/Votre compte permanent/);assert.doesNotMatch(render(),/type="password"/);
 const css=(await readdir(join(root,'dist','assets'))).find(n=>n.endsWith('.css'));await writeFile(join(root,'artifacts','conversion-qa.html'),'<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QA conversion invité</title><link rel="stylesheet" href="/dist/assets/'+css+'"><body><main class="main-content"><section class="panel settings">'+email+'</section><section class="panel settings">'+ready+'</section></main></body></html>');
});

