test('dedicated demonstration stock is labelled openly while ordinary seller listings remain unlabelled',async()=>{const {MarketChestGroups}=await import(pathToFileURL(join(temporary,'MarketChestGroups.mjs')).href);const client=new QueryClient({defaultOptions:{queries:{retry:false,staleTime:Infinity}}});const group={group_key:'demo',seller_id:'npc',seller:'Vesper',name:'Mythique',rarity:5,base_price:80,stock:12,has_tiers:false,expires_at:'2026-11-01',simulated:true};const render=()=>renderToStaticMarkup(createElement(QueryClientProvider,{client},createElement(MemoryRouter,null,createElement(MarketChestGroups,{userId:'qa',search:'',command:async()=>null,busy:false}))));client.setQueryData(['market-chest-groups','qa','',null],[group]);assert.match(render(),/Vendeur simulé/);client.setQueryData(['market-chest-groups','qa','',null],[{...group,simulated:false}]);assert.doesNotMatch(render(),/Vendeur simulé/);});
